import re
with open("app.py", "r", encoding="utf-8") as fh:
    c = fh.read()

# Remove ALL previously injected script blocks (the broken ones) - identified by our function names
pattern = re.compile(r"<script>(?:(?!</script>).)*?(?:alexQ|openPanel|rdlPDF|showReportDl|copyReport|showDownloadBar)(?:(?!</script>).)*?</script>", re.DOTALL)
removed = len(pattern.findall(c))
c = pattern.sub("", c)
print("Removed " + str(removed) + " old script block(s)")

CLEAN_JS = 'var alexQ=["Welcome! The cloud awaits your command. Let us scan for waste and save the planet!","Hi there! Fill in your GCP details and let us make your infrastructure greener!","Ready to crush some cloud waste? Drop your GCP creds and let us roll!","Precision is my protocol. Enter credentials and I shall optimize with surgical accuracy.","Every idle VM we stop plants a virtual tree. Let us make your cloud carbon-neutral!","Your GCP project is waiting to be optimized. Let us cut costs and carbon together!"];\nvar qIdx=0,typeT=null;\nfunction typeText(txt,el,cb){el.textContent="";var i=0;if(typeT)clearInterval(typeT);typeT=setInterval(function(){if(i<txt.length){el.textContent+=txt[i];i++;}else{clearInterval(typeT);if(cb)setTimeout(cb,3000);}},28);}\nfunction cycleQ(){var el=document.getElementById("bot-msg");if(!el)return;el.style.opacity="0";setTimeout(function(){qIdx=(qIdx+1)%alexQ.length;el.style.opacity="1";typeText(alexQ[qIdx],el,cycleQ);},400);}\nfunction openPanel(){var p=document.getElementById("gcp-panel");if(p)p.style.display="flex";loadPanelCfg();setTimeout(function(){var el=document.getElementById("bot-msg");if(el){qIdx=0;typeText(alexQ[0],el,cycleQ);}},300);}\nfunction closePanel(){var p=document.getElementById("gcp-panel");if(p)p.style.display="none";if(typeT)clearInterval(typeT);}\nfunction savePanelCfg(){var k=document.getElementById("cfg-api-key").value.trim();var p=document.getElementById("cfg-project-id").value.trim();var r=document.getElementById("cfg-region").value;var z=document.getElementById("cfg-zone").value.trim()||r+"-a";var el=document.getElementById("bot-msg");if(!k||!p){if(typeT)clearInterval(typeT);el.textContent="Oops! API Key and Project ID are required!";return;}sessionStorage.setItem("gops-cfg",JSON.stringify({apiKey:k,projectId:p,region:r,zone:z}));if(typeT)clearInterval(typeT);el.textContent="All set! GCP credentials saved!";setTimeout(closePanel,1800);}\nfunction testPanelConn(){if(typeT)clearInterval(typeT);var el=document.getElementById("bot-msg");el.textContent="Testing connection...";fetch("/test-connection",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({apiKey:document.getElementById("cfg-api-key").value.trim(),projectId:document.getElementById("cfg-project-id").value.trim(),region:document.getElementById("cfg-region").value})}).then(function(r){return r.json();}).then(function(d){el.textContent=d.success?"Connection successful! All systems GO!":"Connection failed. Check your credentials.";}).catch(function(){el.textContent="Could not reach server.";});}\nfunction loadPanelCfg(){try{var s=JSON.parse(sessionStorage.getItem("gops-cfg")||"{}");if(s.apiKey)document.getElementById("cfg-api-key").value=s.apiKey;if(s.projectId)document.getElementById("cfg-project-id").value=s.projectId;if(s.region)document.getElementById("cfg-region").value=s.region;if(s.zone)document.getElementById("cfg-zone").value=s.zone;}catch(e){}}\nfunction getTxt(){var t=document.getElementById("terminal");return t?(t.innerText||t.textContent):"";}\nfunction dlBlob(content,mime,ext){var b=new Blob([content],{type:mime});var a=document.createElement("a");a.href=URL.createObjectURL(b);a.download="GreenOps_Report_"+new Date().toISOString().split("T")[0]+ext;a.click();}\nfunction rdlTXT(){dlBlob(getTxt(),"text/plain",".txt");}\nfunction rdlPDF(){var w=window.open("","_blank");var safe=getTxt().replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");var h="<!DOCTYPE html><html><head><title>GreenOps Report<\\/title><style>body{font-family:monospace;background:#fff;color:#111;padding:40px;white-space:pre-wrap;line-height:1.7;}h2{color:#0a7d52;border-bottom:1px solid #0a7d52;padding-bottom:8px;}<\\/style><\\/head><body><h2>GreenOps AI Report - "+new Date().toLocaleDateString()+"<\\/h2><pre>"+safe+"<\\/pre><p>Built by Raghu Putta | Google ADK + Gemini 2.5 Pro<\\/p><\\/body><\\/html>";w.document.write(h);w.document.close();setTimeout(function(){w.print();},600);}\nfunction rdlHTML(){var h="<!DOCTYPE html><html><head><title>GreenOps Report<\\/title><style>body{font-family:monospace;background:#0d1117;color:#c9d1d9;padding:40px;white-space:pre-wrap;}h2{color:#34d399;}<\\/style><\\/head><body><h2>GreenOps AI Report<\\/h2><pre>"+getTxt()+"<\\/pre><\\/body><\\/html>";dlBlob(h,"text/html",".html");}\nfunction rdlCSV(){var lines=getTxt().split(String.fromCharCode(10)).filter(function(l){return l.trim();});var nl=String.fromCharCode(10);var csv="No,Content"+nl+lines.map(function(l,i){return (i+1)+","+JSON.stringify(l);}).join(nl);dlBlob(csv,"text/csv",".csv");}\nfunction rdlJSON(){var d={title:"GreenOps AI Report",generated:new Date().toISOString(),built_by:"Raghu Putta",powered_by:"Google ADK + Gemini 2.5 Pro",content:getTxt().split(String.fromCharCode(10)).filter(function(l){return l.trim();})};dlBlob(JSON.stringify(d,null,2),"application/json",".json");}\nfunction rdlCopy(){navigator.clipboard.writeText(getTxt()).then(function(){var b=document.getElementById("rdl-copy");if(b){b.textContent="Copied!";setTimeout(function(){b.textContent="Copy";},2000);}});}\nfunction showReportDl(){var b=document.getElementById("report-dl");if(b)b.style.display="flex";}\nwindow.addEventListener("load",loadPanelCfg);\n'

# Inject verified JS right before </body>
c = c.replace("</body>", "<script>\n" + CLEAN_JS + "\n</script>\n</body>", 1)
print("Clean verified JS injected")

# Sanity checks
print("openPanel in file:", "function openPanel" in c)
print("showReportDl in file:", "function showReportDl" in c)
print("gcp-panel div:", 'id="gcp-panel"' in c)
print("report-dl div:", 'id="report-dl"' in c)
print("done hook:", "showReportDl(); setStatus" in c)

with open("app.py", "w", encoding="utf-8") as fh:
    fh.write(c)
print("ALL DONE!")
